package com.example.evcharging.finance.reconciliation;
import com.example.evcharging.framework.context.RequestContext;import com.example.evcharging.framework.id.IdGenerator;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.dao.DuplicateKeyException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class ChannelBillApplicationService {private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final IdGenerator ids;public ChannelBillApplicationService(JdbcTemplate j,ObjectMapper m,IdGenerator i){jdbc=j;mapper=m;ids=i;}
 public record ChannelTransactionRequest(String paymentNo,String channelTradeNo,long amountFen,long refundAmountFen,String channelStatus,LocalDateTime occurredTime){} public record ImportRequest(String channel,String merchantId,LocalDate businessDate,String sourceFileName,String sourceFileHash,List<ChannelTransactionRequest> records){}
 @Transactional public String importBill(ImportRequest r){long tenant=RequestContext.requireTenantId();String channel=req(r.channel(),"channel").toUpperCase(),merchant=merchant(r.merchantId()),hash=req(r.sourceFileHash(),"sourceFileHash");Objects.requireNonNull(r.businessDate(),"businessDate required");List<ChannelTransactionRequest> records=r.records()==null?List.of():r.records();List<String> prior=jdbc.query("SELECT batch_no FROM finance_channel_bill_batch WHERE tenant_id=? AND channel=? AND merchant_id=? AND source_file_hash=?",(rs,n)->rs.getString(1),tenant,channel,merchant,hash);if(!prior.isEmpty())return prior.get(0);long total=0,refund=0;for(var x:records){if(x.channelTradeNo()==null||x.channelTradeNo().isBlank())throw new IllegalArgumentException("channelTradeNo required");if(x.amountFen()<0||x.refundAmountFen()<0||x.refundAmountFen()>x.amountFen())throw new IllegalArgumentException("invalid channel amount");total=Math.addExact(total,x.amountFen());refund=Math.addExact(refund,x.refundAmountFen());}long id=ids.nextId();String no="CB"+id;LocalDateTime now=LocalDateTime.now();jdbc.update("INSERT INTO finance_channel_bill_batch(id,tenant_id,batch_no,channel,merchant_id,business_date,source_file_name,source_file_hash,record_count,total_amount_fen,total_refund_fen,status,create_time) VALUES (?,?,?,?,?,?,?,?,?,?,?,'IMPORTED',?)",id,tenant,no,channel,merchant,r.businessDate(),r.sourceFileName(),hash,records.size(),total,refund,now);for(var x:records)try{jdbc.update("INSERT INTO finance_channel_transaction(id,tenant_id,batch_id,channel,merchant_id,business_date,payment_no,channel_trade_no,amount_fen,refund_amount_fen,channel_status,occurred_time,raw_payload,create_time) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",ids.nextId(),tenant,id,channel,merchant,r.businessDate(),blank(x.paymentNo()),x.channelTradeNo(),x.amountFen(),x.refundAmountFen(),req(x.channelStatus(),"channelStatus").toUpperCase(),Objects.requireNonNull(x.occurredTime()),json(x),now);}catch(DuplicateKeyException e){throw new IllegalStateException("duplicate channel transaction: "+x.channelTradeNo(),e);}return no;}
 private String json(Object x){try{return mapper.writeValueAsString(x);}catch(Exception e){throw new IllegalStateException(e);}}private static String req(String v,String n){if(v==null||v.isBlank())throw new IllegalArgumentException(n+" required");return v.trim();}private static String merchant(String v){return v==null||v.isBlank()?"DEFAULT":v.trim();}private static String blank(String v){return v==null||v.isBlank()?null:v.trim();}
}
